function telegramWebhookQuery({ query, chatId }) {
  const text = query?.parameter;
  if (typeof text !== "string" || !text.trim() || text.length > 4096)
    throw new Error("Supply one nonempty parameter query value of at most 4096 characters");
  const recipient = typeof chatId === "number" ? String(chatId) : chatId;
  if (
    typeof recipient !== "string" ||
    !/^[1-9][0-9]*$/.test(recipient) ||
    !Number.isSafeInteger(Number(recipient))
  )
    throw new Error("Configure the original recipient’s positive numeric private chat ID");
  return { text, chatId: recipient };
}

return {
  json: telegramWebhookQuery({
    query: $json.query,
    chatId: $("Send the Telegram message").params.chatId,
  }),
};

function telegramWebhookConfirmation({ message, text, chatId }) {
  if (
    !message ||
    !Number.isSafeInteger(message.messageId) ||
    message.messageId <= 0 ||
    !Number.isSafeInteger(message.date) ||
    message.date < 0 ||
    message.chat?.type !== "private" ||
    String(message.chat.id) !== String(chatId) ||
    typeof message.chat.firstName !== "string" ||
    !message.chat.firstName.trim()
  )
    throw new Error(
      "Telegram did not confirm the message in the configured private chat with its recipient’s first name; sending may already have occurred",
    );
  if (typeof text !== "string" || !text) throw new Error("The original message text is missing");
  return { message, response: "Sent message to " + message.chat.firstName + ': "' + text + '"' };
}

if ($json.ok !== true)
  throw new Error("Telegram did not confirm the send; a message may already exist");
const input = $("Read the message and private chat").first().json;
const result = telegramWebhookConfirmation({
  message: {
    messageId: $json.result?.message_id,
    date: $json.result?.date,
    chat: {
      id: $json.result?.chat?.id,
      type: $json.result?.chat?.type,
      firstName: $json.result?.chat?.first_name,
    },
  },
  text: input.text,
  chatId: input.chatId,
});
return { json: { ...$json, response: result.response } };
